Translate("zhCN", "gnarlpine-furbolgs", {
	title = "脊骨熊怪",
	aliases = { "脊骨", "脊骨部族" },
	sections = {
		{
			title = "概述",
			text = [=[脊骨是一个{link:furbolgs}熊怪{/link}部族，他们曾作为{link:night-elves}暗夜精灵{/link}和平的朋友生活在{link:teldrassil}泰达希尔{/link}的山丘中。他们抛弃了旧日的家园，聚集在他们的酋长{link:ursal-the-mauler}大槌乌萨尔{/link}麾下，如今正攻击他们曾经信任的守护者。]=],
		},
		{
			title = "部族的堕落",
			text = [=[树妖{link:tarindrella}塔琳德拉{/link}相信，只有邪能苔藓才能造成这样的变化。{link:ursal-the-mauler}乌萨尔{/link}利用它的力量把他的族人逼疯。他们被遗弃的营地中留下的图腾讲述了更多。脊骨熊怪开始梦见一道将毁灭他们的巨大阴影。他们的恐惧化为愤怒，梦中的阴影变成了他们的精灵朋友。]=],
		},
		{
			title = "疯狂之举",
			text = [=[• 他们伏击了看守者{link:gaerolas-talvethren}盖洛拉斯·塔文斯伦{/link}，洗劫了{link:starbreeze-village}星风村{/link}。
• 他们闯入{link:ban-ethil-barrow-den}班奈希尔兽穴{/link}，他们的萨满祭司学会了把沉睡德鲁伊的灵魂与肉体分离。
• 他们在通往{link:darnassus}达纳苏斯{/link}的道路上和{link:pools-of-arlithrien}阿里斯瑞恩之池{/link}的巡逻队中劫掠。
• 他们的秘法师噬梦者{link:feero-ironhand}费罗{/link}希塔斯偷走了一颗从梦境中汲取力量的翡翠。]=],
		},
		{ title = "未载之事", text = "至今无人知道邪能苔藓从何而来，也不知道{link:furbolgs}熊怪{/link}能否被治愈。" },
	},
})

Translate("zhCN", "corruption-of-teldrassil", {
	title = "泰达希尔的腐化",
	sections = {
		{
			title = "概述",
			text = [=[泰达希尔的腐化是自这棵新世界之树长成以来在其中蔓延的病害。女祭司和德鲁伊处处都能看到它的迹象：在野兽中，在植物中，在{link:furbolgs}熊怪{/link}中，甚至在土壤中。]=],
		},
		{
			title = "迹象",
			text = [=[• 奇异的野兽从这棵树的土地中升起，小树精变得愤怒，长满有毒的肿瘤。
• 邪能苔藓污染了{link:shadowglen}幽影谷{/link}的格{link:farmer-ray}雷{/link}尔、{link:the-oracle-glade}神谕林地{/link}的{link:harpies}鹰身人{/link}和{link:gnarlpine-furbolgs}脊骨熊怪{/link}。
• {link:satyrs}萨特{/link}邪恶的泽索尔扭曲了这棵树的蜘蛛，其他萨特玷污了它的月亮井。
• 受艾露恩宠爱的蜘蛛{link:lady-sathrah}萨丝拉{/link}已经疯了。
• 来自远方的植物在树上发芽，与它的土壤发生着奇异的反应。]=],
		},
		{
			title = "起因之问",
			text = [=[{link:corithras-moonrage}科瑞萨斯·月怒{/link}把这棵树的许多麻烦归因于它在没有诺兹多姆和{link:alexstrasza}阿莱克丝塔萨{/link}祝福的情况下生长。{link:fandral-staghelm}范达尔·鹿盔{/link}肩负着寻找补救之法的重担，他担心自己的工作可能永远无法完成。{link:moonglade}月光林地{/link}与{link:darnassus}达纳苏斯{/link}的德鲁伊彼此猜疑，而持续的腐化丝毫没有缓解这种猜疑。]=],
		},
		{ title = "未载之事", text = "至今没有编年史指出邪能苔藓的源头，或解释这种污染最初是如何进入这棵树的。" },
	},
})
